"""
Client for interacting with the qBraid Skills API.

"""

import hashlib
import os
import shutil
import tarfile
import tempfile
from pathlib import Path
from typing import Any, Optional

import requests

from qbraid_core.client import QbraidClientV1
from qbraid_core.exceptions import RequestsApiError
from qbraid_core.registry import register_client

from .exceptions import SkillInstallError, SkillNotFoundError, SkillsServiceRequestError
from .schemas import (
    RedeemCodeResponse,
    ShareCodeResponse,
    SharedWithResponse,
    ShareTarget,
    Skill,
    SkillCreateRequest,
    SkillCreateResponse,
    SkillDownload,
    SkillUpload,
    Visibility,
)


class SkillTarget:
    """Supported AI coding tools for skill installation."""

    CLAUDE_CODE = "claude-code"
    CODEX = "codex"
    CURSOR = "cursor"
    COPILOT = "copilot"
    ALL = "all"


# Mapping of tool names to their skill directories
SKILL_PATHS: dict[str, Path] = {
    SkillTarget.CLAUDE_CODE: Path.home() / ".claude" / "skills",
    SkillTarget.CODEX: Path.home() / ".agents" / "skills",
    SkillTarget.CURSOR: Path.home() / ".cursor" / "skills",
    SkillTarget.COPILOT: Path.home() / ".copilot" / "skills",
}


def get_skills_install_path(target: str = SkillTarget.CLAUDE_CODE) -> Path:
    """Get the skills installation path for a specific tool."""
    if target not in SKILL_PATHS:
        raise ValueError(f"Unknown target '{target}'. Use one of: {list(SKILL_PATHS.keys())}")
    return SKILL_PATHS[target]


def get_all_skill_paths() -> dict[str, Path]:
    """Get skill installation paths for all supported tools."""
    return SKILL_PATHS.copy()


@register_client()
class SkillsClient(QbraidClientV1):
    """Client for interacting with the qBraid Skills API."""

    # =========================================================================
    # Core CRUD Operations
    # =========================================================================

    def list_skills(
        self,
        query: Optional[str] = None,
        app_id: Optional[str] = None,
        author_id: Optional[str] = None,
        tags: Optional[list[str]] = None,
        visibility: Optional[str] = None,
        sort: Optional[str] = None,
        page: Optional[int] = None,
        limit: Optional[int] = None,
    ) -> list[Skill]:
        """List available skills with optional filters.

        Args:
            query: Full-text search query (searches name, description, tags).
            app_id: Filter by linked app ID.
            author_id: Filter by owner's user ID.
            tags: Filter by tags.
            visibility: Filter by visibility (private, public, shared).
            sort: Sort order (newest, oldest, popular, name).
            page: Page number for pagination.
            limit: Results per page (default 50, max 100).

        Returns:
            List of Skill objects matching the filters.
        """
        params: dict[str, Any] = {}
        if query is not None:
            params["q"] = query
        if app_id is not None:
            params["appId"] = app_id
        if author_id is not None:
            params["authorId"] = author_id
        if tags is not None:
            params["tags"] = ",".join(tags)
        if visibility is not None:
            params["visibility"] = visibility
        if sort is not None:
            params["sort"] = sort
        if page is not None:
            params["page"] = page
        if limit is not None:
            params["limit"] = limit

        try:
            response = self.session.get("/skills", params=params if params else None)
            resp_json = response.json()
            skills_data = resp_json.get("data", [])
            return [Skill.model_validate(s) for s in skills_data]
        except RequestsApiError as err:
            raise SkillsServiceRequestError(f"Failed to list skills: {err}") from err

    def get_skill(self, slug: str) -> Skill:
        """Get details for a specific skill.

        Args:
            slug: The skill slug (unique identifier).

        Returns:
            Skill object with full details.
        """
        try:
            response = self.session.get(f"/skills/{slug}")
            resp_data = response.json().get("data", response.json())
            return Skill.model_validate(resp_data)
        except RequestsApiError as err:
            err_str = str(err).lower()
            if "404" in err_str or "not found" in err_str:
                raise SkillNotFoundError(f"Skill '{slug}' not found") from err
            raise SkillsServiceRequestError(f"Failed to get skill '{slug}': {err}") from err

    def create_skill(self, request: SkillCreateRequest) -> SkillCreateResponse:
        """Create a new skill and get an upload URL.

        Args:
            request: Skill creation request with metadata.

        Returns:
            SkillCreateResponse with skill data and signed upload URL.
        """
        try:
            response = self.session.post(
                "/skills", json=request.model_dump(by_alias=True, exclude_none=True)
            )
            resp_data = response.json().get("data", response.json())
            return SkillCreateResponse.model_validate(resp_data)
        except RequestsApiError as err:
            raise SkillsServiceRequestError(f"Failed to create skill: {err}") from err

    def update_skill(
        self,
        slug: str,
        name: Optional[str] = None,
        description: Optional[str] = None,
        version: Optional[str] = None,
        tags: Optional[list[str]] = None,
        compatibility: Optional[list[str]] = None,
        visibility: Optional[Visibility] = None,
    ) -> Skill:
        """Update skill metadata.

        Args:
            slug: The skill slug.
            name: New display name.
            description: New description.
            version: New version.
            tags: New tags list.
            compatibility: New compatibility list.
            visibility: New visibility level.

        Returns:
            Updated Skill object.
        """
        data: dict[str, Any] = {}
        if name is not None:
            data["name"] = name
        if description is not None:
            data["description"] = description
        if version is not None:
            data["version"] = version
        if tags is not None:
            data["tags"] = tags
        if compatibility is not None:
            data["compatibility"] = compatibility
        if visibility is not None:
            data["visibility"] = (
                visibility.value if isinstance(visibility, Visibility) else visibility
            )

        try:
            response = self.session.put(f"/skills/{slug}", json=data)
            resp_data = response.json().get("data", response.json())
            return Skill.model_validate(resp_data)
        except RequestsApiError as err:
            err_str = str(err).lower()
            if "404" in err_str or "not found" in err_str:
                raise SkillNotFoundError(f"Skill '{slug}' not found") from err
            raise SkillsServiceRequestError(f"Failed to update skill '{slug}': {err}") from err

    def delete_skill(self, slug: str) -> None:
        """Delete a skill (owner or admin only).

        Args:
            slug: The skill slug.
        """
        try:
            self.session.delete(f"/skills/{slug}")
        except RequestsApiError as err:
            err_str = str(err).lower()
            if "404" in err_str or "not found" in err_str:
                raise SkillNotFoundError(f"Skill '{slug}' not found") from err
            raise SkillsServiceRequestError(f"Failed to delete skill '{slug}': {err}") from err

    # =========================================================================
    # Upload/Download Operations
    # =========================================================================

    def get_download_url(self, slug: str) -> SkillDownload:
        """Get a signed download URL for a skill's tarball.

        Args:
            slug: The skill slug.

        Returns:
            SkillDownload with signed URL and expiration.
        """
        try:
            response = self.session.get(f"/skills/{slug}/download")
            resp_data = response.json().get("data", response.json())
            return SkillDownload.model_validate(resp_data)
        except RequestsApiError as err:
            err_str = str(err).lower()
            if "404" in err_str or "not found" in err_str:
                raise SkillNotFoundError(f"Skill '{slug}' not found") from err
            raise SkillsServiceRequestError(
                f"Failed to get download URL for skill '{slug}': {err}"
            ) from err

    def get_upload_url(self, slug: str) -> SkillUpload:
        """Get a signed upload URL for re-uploading a skill.

        Args:
            slug: The skill slug.

        Returns:
            SkillUpload with signed URL and expiration.
        """
        try:
            response = self.session.post(f"/skills/{slug}/upload-url")
            resp_data = response.json().get("data", response.json())
            return SkillUpload.model_validate(resp_data)
        except RequestsApiError as err:
            err_str = str(err).lower()
            if "404" in err_str or "not found" in err_str:
                raise SkillNotFoundError(f"Skill '{slug}' not found") from err
            raise SkillsServiceRequestError(
                f"Failed to get upload URL for skill '{slug}': {err}"
            ) from err

    def confirm_upload(self, slug: str, checksum: Optional[str] = None) -> dict[str, Any]:
        """Confirm that skill upload is complete.

        Args:
            slug: The skill slug.
            checksum: Optional SHA-256 checksum of uploaded file.

        Returns:
            Confirmation response with status.
        """
        data: dict[str, Any] = {}
        if checksum:
            data["checksum"] = checksum

        try:
            response = self.session.post(f"/skills/{slug}/confirm-upload", json=data)
            return response.json().get("data", response.json())
        except RequestsApiError as err:
            raise SkillsServiceRequestError(
                f"Failed to confirm upload for skill '{slug}': {err}"
            ) from err

    def upload_skill(
        self,
        slug: str,
        directory: Path,
        progress_callback: Optional[Any] = None,
    ) -> dict[str, Any]:
        """Create a tarball from a directory and upload it to the skill's signed URL.

        This handles the full upload workflow: tar creation → upload → confirm.

        Args:
            slug: The skill slug.
            directory: Path to the skill directory to upload.
            progress_callback: Optional callback for progress updates.

        Returns:
            dict with upload confirmation response.

        Raises:
            FileNotFoundError: If directory doesn't exist.
            SkillsServiceRequestError: If upload or confirmation fails.
        """
        directory = Path(directory)
        if not directory.is_dir():
            raise FileNotFoundError(f"Skill directory not found: {directory}")

        with tempfile.TemporaryDirectory() as tmpdir:
            # Step 1: Create tarball
            if progress_callback:
                progress_callback("Creating archive...")

            archive_path = Path(tmpdir) / f"{slug}.tar.gz"
            with tarfile.open(archive_path, "w:gz") as tar:
                for item in directory.iterdir():
                    tar.add(item, arcname=item.name)

            # Step 2: Get signed upload URL
            if progress_callback:
                progress_callback("Getting upload URL...")

            upload_info = self.get_upload_url(slug)

            # Step 3: Upload to signed URL
            if progress_callback:
                progress_callback("Uploading...")

            file_size = archive_path.stat().st_size
            try:
                with open(archive_path, "rb") as f:
                    resp = requests.put(
                        upload_info.upload_url,
                        data=f,
                        headers={
                            "Content-Type": "application/gzip",
                            "Content-Length": str(file_size),
                        },
                        timeout=600,
                    )
                    resp.raise_for_status()
            except Exception as err:
                raise SkillsServiceRequestError(f"Failed to upload skill '{slug}': {err}") from err

            # Step 4: Confirm upload
            if progress_callback:
                progress_callback("Confirming upload...")

            sha256 = hashlib.sha256()
            with open(archive_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    sha256.update(chunk)
            checksum = sha256.hexdigest()

            result = self.confirm_upload(slug, checksum=checksum)

            return {
                "slug": slug,
                "size_bytes": file_size,
                "checksum": checksum,
                **result,
            }

    # =========================================================================
    # Sharing Operations
    # =========================================================================

    def share_skill(
        self,
        slug: str,
        email: str,
        permissions: list[str],
    ) -> dict[str, Any]:
        """Share a skill with a user.

        Args:
            slug: The skill slug.
            email: Email of the user to share with.
            permissions: List of permissions ('read' and/or 'write').

        Returns:
            Share confirmation response.
        """
        data = {
            "targetType": ShareTarget.USER.value,
            "email": email,
            "permissions": permissions,
        }
        try:
            response = self.session.post(f"/skills/{slug}/share", json=data)
            return response.json().get("data", response.json())
        except RequestsApiError as err:
            raise SkillsServiceRequestError(f"Failed to share skill '{slug}': {err}") from err

    def revoke_skill_access(
        self,
        slug: str,
        email: str,
        permissions: list[str],
    ) -> dict[str, Any]:
        """Revoke a user's access to a skill.

        Args:
            slug: The skill slug.
            email: Email of the user to revoke access from.
            permissions: List of permissions to revoke ('read' and/or 'write').

        Returns:
            Revocation confirmation response.
        """
        data = {
            "targetType": ShareTarget.USER.value,
            "email": email,
            "permissions": permissions,
        }
        try:
            response = self.session.delete(f"/skills/{slug}/share", json=data)
            return response.json().get("data", response.json())
        except RequestsApiError as err:
            raise SkillsServiceRequestError(
                f"Failed to revoke access for skill '{slug}': {err}"
            ) from err

    def get_shared_users(self, slug: str) -> SharedWithResponse:
        """Get list of users with access to a skill.

        Args:
            slug: The skill slug.

        Returns:
            SharedWithResponse with read and write access users.
        """
        try:
            response = self.session.get(f"/skills/{slug}/shared-with")
            resp_data = response.json().get("data", response.json())
            return SharedWithResponse.model_validate(resp_data)
        except RequestsApiError as err:
            raise SkillsServiceRequestError(
                f"Failed to get shared users for skill '{slug}': {err}"
            ) from err

